static int char_to_val(int c, unsigned radix) {
  int d = -1;
  if (c >= '0' && c <= '9') d = c - '0';
  else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
  else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
  return (d >= 0 && (unsigned)d < radix) ? d : -1;
}

/* convert bin/qua/oct/hex floating-point notation to double (adapted from Skint n.c)
 * bbits: bits per mantissa digit (1=bin, 2=qua, 3=oct, 4=hex)
 * 'e' (ebase = eradix = 1<<bbits) or 'p' (ebase = 2, eradix = 10) */
double po2b_atod(const char *s, char **endp, unsigned bbits) {
  const char *p = s; uint64_t sig = 0; double d;
  int neg, dotpos = -1, ndigits = 0, hxcount = 0, echar;
  int first_digit_idx = -1, first_digit_val = 0, sticky = 0;
  long pexp = 0; unsigned base = 1 << bbits;

  while (isspace((unsigned char)*p)) ++p;
  neg = (*p == '-');
  if (*p == '-' || *p == '+') ++p;

  if (bbits == 4 && p[0] == '0' && (p[1] == 'x' || p[1] == 'X') &&
      (char_to_val((unsigned char)p[2], 16) >= 0 || p[2] == '.')) {
    p += 2;
  }

  /* parse mantissa */
  for (;; ++p) {
    int c = (unsigned char)*p;
    int dig = (c == '.' && dotpos < 0) ? -2 : char_to_val(c, base);
    if (dig == -1) break; /* not a valid digit */
    if (dig == -2) { dotpos = ndigits; continue; }
    if (dig != 0 || first_digit_idx >= 0) {
      if (first_digit_idx < 0) {
        first_digit_idx = ndigits;
        first_digit_val = dig;
      }
      /* keep as many digits as fits in 60 bits to prevent uint64_t overflow */
      if ((hxcount + 1) * bbits <= 60) {
        sig = (sig << bbits) | (unsigned)dig;
        hxcount++;
      } else if (dig > 0) {
        sticky = 1;
      }
    }
    ++ndigits;
  }

  if (ndigits == 0) {
    if (endp) *endp = (char *)s;
    errno = EDOM; return 0.0;
  }
  if (dotpos < 0) dotpos = ndigits;

  /* parse exponent */
  echar = tolower((unsigned char)*p);
  if ((bbits < 4 && echar == 'e') || echar == 'p') {
    const char *r = p + 1;
    int pneg;
    unsigned eradix = (echar == 'p') ? 10 : base;
    if (echar == 'p' &&
        (*r == 'f' || *r == 'F' || *r == 'd' || *r == 'D' ||
         *r == 's' || *r == 'S' || *r == 'l' || *r == 'L') &&
        (r[1] == '+' || r[1] == '-' || char_to_val((unsigned char)r[1], 10) >= 0)) {
      ++r;
    }
    pneg = (*r == '-');
    if (*r == '-' || *r == '+') r++;
    if (char_to_val((unsigned char)*r, eradix) >= 0) {
      pexp = 0;
      while (1) {
        int dig = char_to_val((unsigned char)*r, eradix);
        if (dig < 0) break;
        if (pexp < 1000000) pexp = pexp * eradix + dig;
        ++r;
      }
      if (pneg) pexp = -pexp;
      p = r;
    }
  }
  if (endp) *endp = (char *)p;

  if (first_digit_idx < 0) {
    return neg ? -0.0 : 0.0;
  } else {
    int msb_offset = 0;
    int temp_v = first_digit_val;
    int target_bits, shift, round_bit;
    long ldx, exp_msb, binary_pexp;

    /* MSB offset within the first digit (e.g., octal '7' is 2, binary '1' is 0) */
    while (temp_v >>= 1) ++msb_offset;
    /* calculate binary weight */
    binary_pexp = (echar == 'p') ? pexp : pexp * (long)bbits;
    ldx = binary_pexp + (long)(dotpos - 1 - first_digit_idx) * (long)bbits;
    ldx -= (long)(hxcount - 1) * (long)bbits;
    /* binary weight of the MSB */
    exp_msb = ldx + (long)(hxcount - 1) * (long)bbits + msb_offset;

    /* determine precision (IEEE 754 double) */
    if (exp_msb >= (long)DBL_MIN_EXP - 1) {
      target_bits = DBL_MANT_DIG;
    } else {
      target_bits = (int)(exp_msb - (long)(DBL_MIN_EXP - DBL_MANT_DIG - 1));
      if (target_bits < 0) target_bits = 0;
    }

    /* rounding logic (RNE) */
    /* total bits currently in sig: (digits - 1)*bbits + (msb_offset + 1) */
    shift = (int)((hxcount - 1) * bbits + msb_offset + 1) - target_bits;
    if (shift > 0) {
      if (shift >= 64) {
        sticky |= (sig != 0);
        sig = 0; round_bit = 0;
      } else {
        sticky |= ((sig & ((UINT64_C(1) << (shift - 1)) - 1)) != 0);
        round_bit = (int)((sig >> (shift - 1)) & 1);
        sig >>= shift;
      }
      if (round_bit && (sticky || (sig & 1))) {
        sig++;
        if (target_bits > 0 && (sig >= (UINT64_C(1) << target_bits))) {
          sig >>= 1; ldx++;
        }
      }
      ldx += shift;
    } else if (shift < 0) {
      sig <<= -shift;
      ldx += shift;
    }

    /* result */
    d = ldexp((double)sig, (int)ldx);
    if (d <= -HUGE_VAL || d >= HUGE_VAL) errno = ERANGE;
    else if (d == 0.0) errno = ERANGE; /* subnormal underflow */
    return neg ? -d : d;
  }
}

static char gn_digit(int d) {
  return (char)((d < 10) ? ('0' + d) : ('a' + (d - 10)));
}

static char *render_exp(char *p, int echar, long exp_val) {
  char tmp[32];
  int i = 0;
  unsigned long u;
  *p++ = (char)echar;
  if (exp_val < 0) {
    *p++ = '-';
    u = (unsigned long)(-exp_val);
  } else {
    *p++ = '+';
    u = (unsigned long)exp_val;
  }
  do {
    tmp[i++] = (char)('0' + (u % 10));
    u /= 10;
  } while (u > 0);
  while (i > 0) *p++ = tmp[--i];
  *p = '\0';
  return p;
}

/* Format double in power-of-2 base (bbits = 1, 2, 3, or 4) (adapted from Skint n.c) */
char* po2b_dtoa(double x, char *buf, size_t buflen, unsigned bbits, int echar, int mode, int prc) {
  enum { MAX_DIGS = 64 };
  int digs[MAX_DIGS];
  int max_digs, ndig, fdigs, i;
  int base = 1 << bbits;
  int neg = 0;
  int e;
  double m;
  char *p = buf;

  assert(buf != NULL && buflen >= 8);
  assert(1 <= bbits && bbits <= 4);
  if (mode == 'g') mode = 'g';
  else if (mode == 'e' || mode == 'a') mode = 'a';
  else mode = 'g';

  if (!is_finite(x)) {
    const char *s = is_nan(x) ? "+nan.0" : (x < 0) ? "-inf.0" : "+inf.0";
    strncpy(buf, s, buflen - 1);
    buf[buflen - 1] = '\0';
    return buf;
  }

  if (x == 0.0) {
    if (is_negzero(x)) *p++ = '-';
    *p++ = '0';
    *p++ = '.';
    if (mode == 'a') {
      fdigs = (prc < 0) ? 0 : prc;
      for (i = 0; i < fdigs; ++i) *p++ = '0';
      if (fdigs == 0) *p++ = '0';
    } else {
      *p++ = '0';
    }
    render_exp(p, echar, 0);
    return buf;
  }

  if (x < 0.0) {
    neg = 1;
    x = -x;
  }

  m = frexp(x, &e);
  m *= 2.0;
  e -= 1;

  if (e < DBL_MIN_EXP - 1) {
    int shift = e - (DBL_MIN_EXP - 1);
    m = ldexp(m, shift);
    e = DBL_MIN_EXP - 1;
  }

  max_digs = 1 + (int)((52 + bbits - 1) / bbits);
  assert(max_digs <= MAX_DIGS);

  for (i = 0; i < max_digs; ++i) {
    int d = (int)m;
    if (d >= base) d = base - 1;
    digs[i] = d;
    m = (m - (double)d) * (double)base;
  }

  if (mode == 'a') {
    fdigs = (prc < 0) ? 0 : prc;
    ndig = 1 + fdigs;
  } else {
    ndig = (prc <= 0) ? max_digs : ((prc > max_digs) ? max_digs : prc);
  }

  if (ndig < max_digs) {
    int half = base / 2;
    int rdig = digs[ndig];
    int sticky = (m > 0.0);
    for (i = ndig + 1; i < max_digs; ++i) {
      if (digs[i] != 0) { sticky = 1; break; }
    }
    if (rdig > half || (rdig == half && (sticky || (ndig > 0 && (digs[ndig - 1] & 1))))) {
      int k = ndig - 1;
      while (k >= 0) {
        if (++digs[k] < base) break;
        digs[k] = 0;
        --k;
      }
      if (k < 0) {
        if (digs[0] == 0) {
          digs[0] = 1;
          e += (int)bbits;
        }
      }
    }
  }

  if (mode == 'g') {
    while (ndig > 2 && digs[ndig - 1] == 0) --ndig;
    if (ndig < 2) ndig = 2;
  }

  if (neg) *p++ = '-';
  *p++ = gn_digit(digs[0]);
  *p++ = '.';
  if (ndig <= 1) {
    *p++ = '0';
  } else {
    for (i = 1; i < ndig; ++i) {
      *p++ = gn_digit((i < max_digs) ? digs[i] : 0);
    }
  }
  render_exp(p, echar, (long)e);
  return buf;
}
extern int strtofxfl(char *s, int radix, long *pl, double *pd);
int strtofxfl(char *s, int radix, long *pl, double *pd) {
  extern int strcmp_ci(char *s1, char *s2); /* defined below */
  char *e; int conv = 0, eno = errno; long l; double d;
  for (; s[0] == '#'; s += 2) {
    switch (s[1]) {
      case 'b': case 'B': radix = 2; break;
      case 'o': case 'O': radix = 8; break;
      case 'd': case 'D': radix = 10; break;
      case 'x': case 'X': radix = 16; break;
      case 'e': case 'E': conv = 'e'; break;
      case 'i': case 'I': conv = 'i'; break;
      default: return 0;
    }
  }
  if (isspace((unsigned char)*s)) return 0;
  if (conv != 'i') {
    for (e = s; *e; ++e) {
      if ((radix < 16 && (*e == 'e' || *e == 'E')) || *e == '.' || *e == 'p' || *e == 'P') break;
    }
    if (!*e) {
      l = (errno = 0, strtol(s, &e, radix));
      if (!errno && !*e && e != s && FIXNUM_MIN <= l && l <= FIXNUM_MAX)
        return (errno = eno, *pl = l, 'e');
      if (conv == 'e') return (errno = eno, 0);
    }
  }
  e = s; errno = 0;
  if ((*s == '+' || *s == '-') && strcmp_ci(s+1, "inf.0") == 0) {
    d = (*s == '-' ? -HUGE_VAL : HUGE_VAL); e = s + strlen(s);
  } else if ((*s == '+' || *s == '-') && strcmp_ci(s+1, "nan.0") == 0) {
    d = HUGE_VAL - HUGE_VAL; e = s + strlen(s);
  } else if (radix == 10) {
    d = strtod(s, &e);
  } else if (radix == 2 || radix == 8 || radix == 16) {
    d = po2b_atod(s, &e, (radix == 2) ? 1 : (radix == 8) ? 3 : 4);
  } else return (errno = eno, 0);
  if (errno || *e || e == s) return (errno = eno, 0);
  if ((conv == 'e') && ((l=(long)d) < FIXNUM_MIN || l > FIXNUM_MAX || (double)l != d))
    return (errno = eno, 0); /* can't be converted to an exact number */
  return (errno = eno, (conv == 'e') ? (*pl = fxflo(d), 'e') : (*pd = d, 'i'));
}
